<?php use App\Core\Security;require BASE_PATH.'/app/Views/layout/header.php';?><div class="d-flex justify-content-between mb-3"><h2>User management</h2><a class="btn btn-pink" href="<?= BASE_URL ?>/?page=users&action=create">+ Add user</a></div><div class="card p-3"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?= Security::e($u['name']) ?></td><td><?= Security::e($u['email']) ?></td><td><?= Security::e(ucfirst($u['role'])) ?></td><td><?= Security::e(ucfirst($u['status'])) ?></td><td><form method="post" action="<?= BASE_URL ?>/?page=users&action=delete" onsubmit="return confirm('Delete this user?');"><input type="hidden" name="_csrf" value="<?= Security::csrf() ?>"><input type="hidden" name="id" value="<?= $u['id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';?>
